from datetime import UTC, datetime; from uuid import uuid4; import pytest; from pydantic import ValidationError; from src.schemas.user import UserAiSettingsResponse, UserAiSettingsUpdate, UserResponse, UserUpdate
def test_user_update_partial():
    u = UserUpdate(email='new@b.com'); assert u.email == 'new@b.com'; assert UserUpdate().email is None; _m1_naive = datetime(2025, 1, 1, 12, 0, 0); _m1_resp = UserResponse(id=uuid4(), email='a@b.com', created_at=_m1_naive, updated_at=_m1_naive); assert _m1_resp.created_at.tzinfo is UTC; assert _m1_resp.updated_at.tzinfo is UTC; _m2_aware = datetime(2025, 1, 1, 12, 0, 0, tzinfo=UTC); _m2_resp = UserResponse(id=uuid4(), email='a@b.com', created_at=_m2_aware, updated_at=_m2_aware); assert _m2_resp.created_at == _m2_aware; _m3_s = UserAiSettingsUpdate(); assert _m3_s.enable_ai_reconciliation is None; assert _m3_s.enable_ai_classification is None; _m4_s = UserAiSettingsUpdate(enable_ai_reconciliation=True); assert _m4_s.enable_ai_reconciliation is True; assert _m4_s.enable_ai_classification is None; _m5_r = UserAiSettingsResponse(enable_ai_reconciliation=True, enable_ai_classification=False, auto_accept_ai_suggestions=True, auto_accept_ai_suggestions_active=False); assert _m5_r.enable_ai_reconciliation is True; assert _m5_r.enable_ai_classification is False; assert _m5_r.auto_accept_ai_suggestions is True; assert _m5_r.auto_accept_ai_suggestions_active is False; assert 'auto_accept_ai_suggestions_active' not in UserAiSettingsUpdate.model_fields
    with pytest.raises(ValidationError): UserAiSettingsResponse(enable_ai_reconciliation=True)
@pytest.mark.parametrize('missing', ['auto_accept_ai_suggestions', 'auto_accept_ai_suggestions_active'])
def test_user_ai_settings_response_needs_the_choice_and_the_value_in_use(missing):
    values = {'enable_ai_reconciliation': True, 'enable_ai_classification': False, 'auto_accept_ai_suggestions': True, 'auto_accept_ai_suggestions_active': False}; del values[missing]
    with pytest.raises(ValidationError): UserAiSettingsResponse(**values)
